#include "at/AtIoJam.h"
#include "AtIoJamCommon.h"

AtIoJamNameTable::AtIoJamNameTable() {
    m_names = 0;
    m_extensions = 0;
    m_unknown08 = -1;
    m_unknown0C = -1;
    m_nameCount = 0;
    m_extensionCount = 0;
}

AtIoJamNameTable::~AtIoJamNameTable() {
    m_names = 0;
    m_extensions = 0;
    m_unknown08 = -1;
    m_unknown0C = -1;
    m_nameCount = 0;
    m_extensionCount = 0;
}

void AtIoJamNameTable::Init(const char* names, unsigned int nameCount, unsigned int extensionCount) {
    if (m_names) {
        m_names = 0;
        m_extensions = 0;
        m_unknown08 = -1;
        m_unknown0C = -1;
        m_nameCount = 0;
        m_extensionCount = 0;
    }
    m_names = names;
    m_extensionCount = extensionCount;
    m_nameCount = nameCount;
    m_extensions = names + nameCount * 8;
}

// Binary search with a halving stride, then a linear scan from the lower bound. The bound only moves past entries known to
// sort before the key, so a present entry is always found, and a greater entry ends the scan.
int AtIoJamNameTable::Search(const char* key, const char* table, unsigned int width, int count) {
    unsigned int stride = (unsigned int)count >> 2;
    int mid = (unsigned int)count >> 1;
    int low = 0;
    while (stride > 5) {
        int order = strncmp(table + mid * width, key, width);
        if (order == 0) {
            return mid;
        }
        if (order < 0) {
            if (low < mid) {
                low = mid;
            }
            mid += stride;
        } else {
            mid -= stride;
        }
        stride = (int)stride / 2;
    }
    for (int i = low; i < count; i++) {
        int order = strncmp(table + i * width, key, width);
        if (order == 0) {
            return i;
        }
        if (order > 0) {
            break;
        }
    }
    return -1;
}

int AtIoJamNameTable::FindName(const char* name) {
    if (*name == 0) {
        return -1;
    }
    return Search(name, m_names, 8, m_nameCount);
}

int AtIoJamNameTable::FindExtension(const char* ext) {
    if (ext == 0 || *ext == 0) {
        return 0;
    }
    return Search(ext, m_extensions, 4, m_extensionCount);
}

int AtIoJamNameTable::GetFullName(unsigned int name, unsigned int extension, char* out) {
    if (name >= m_nameCount || extension >= m_extensionCount) {
        *out = 0;
        return 0;
    }
    ((unsigned int*)out)[0] = 0;
    ((unsigned int*)out)[1] = 0;
    ((unsigned int*)out)[2] = 0;
    strncpy(out, m_names + name * 8, 8);
    strcat(out, ".");
    strncat(out, m_extensions + extension * 4, 3);
    return 1;
}

// A pattern's leading '*' matches anything. Original behaviour: fullName is copied to 16 bytes with no length check.
int AtIoJamNameTable::Matches(const char* fullName, const char* namePattern, const char* extPattern) {
    char name[16];
    if (strlen(fullName) == 0 || strlen(namePattern) == 0) {
        return 0;
    }
    strcpy(name, fullName);
    char* ext = strchr(name, '.');
    if (ext) {
        *ext = 0;
        ext++;
    } else {
        ext = name + strlen(name);
    }
    if (strncmp(extPattern, ext, 4) != 0 && *extPattern != '*') {
        return 0;
    }
    if (strncmp(namePattern, name, 8) != 0 && *namePattern != '*') {
        return 0;
    }
    return 1;
}

